  }
  hijas.forEach(function (c, i) {
    if (c && c.displayUrl) out.push(Object.assign({ post_id: sc + '-c' + (i + 1), tipo: 'post_hijo', src: c.displayUrl, posicion: 'hijo-' + (i + 1), indice: i + 1, medio: aMedio(c.type, c.productType) }, base))
