      : (['website_content_scraper', 'competitor_website_scraper'].includes(ctx.apify_function) ? 'una web raspada es materia prima · vive en client_web_pages' : null),
    should_brain: !['website_content_scraper', 'own_google_maps_profile', 'competitor_website_scraper'].includes(ctx.apify_function) && !ensayo && (ctx.sections || []).length > 0 && (ctx.destination === 'brain_rag' || ctx.destination === 'both'),
    should_callback: ctx.destination === 'callback_url' || ctx.destination === 'both',
