  own_google_maps_profile: ($json) => ({ searchStringsArray: $json.params.searchStringsArray || $json.params.searchStrings || ($json.params.query ? [$json.params.query] : []), locationQuery: $json.params.locationQuery || $json.params.location || '', maxCrawledPlacesPerSearch: $json.params.resultsLimit || 10, language: $json.params.language || 'es' }),
