  youtube_channel_scraper: ($json) => ({ startUrls: ($json.params.startUrls || [{ url: 'https://www.youtube.com/' + (($json.params.handles && $json.params.handles[0]) || '@NatGeo') }]), maxResultStreams: $json.params.maxResultStreams || $json.params.maxItems || 5 }),
