// ───────────────────────────── el chequeo (determinista · sin modelo) ─────────────────────────────
/** La clave de foto que declara la pieza: «F08» o { foto: 'F08', por_que } · null si declaró «ninguna» */
function fotoDeclarada(pieza) {
  var v = pieza && pieza.foto_referencia
