}
function nombraProducto(texto, catalogo, prot) {
  var r = raicesDe(texto, [])
  var otros = (catalogo || []).filter(function (e) { return !prot || e.nombre !== prot.nombre }).filter(function (e) { return e.raices.some(function (x) { return r.indexOf(x) !== -1 }) })
  var propio = !!prot && prot.raices.some(function (x) { return r.indexOf(x) !== -1 })
  return { otros: otros.map(function (e) { return e.nombre }), propio: propio }
}
/**
 * `ctx` = { regla_activa, sin_foto_del_producto, producto_del_brief, raices_del_producto, fotos: [{ref, rol, producto}], catalogo }
 * Devuelve [{ chequeo, detalle, fatal }]. Los FATALES son los tres que dejan pasar un plato por otro.
 */
function chequearFotoReferencia(pieza, ctx, brief) {
  var h = []
  if (!ctx || !ctx.regla_activa) return h
  var falla = function (chequeo, detalle, fatal) { h.push({ chequeo: chequeo, detalle: detalle, fatal: fatal === true }) }
  var tipo = sinTildes(brief && brief.tipo_de_pieza)
  if (tipo !== 'imagen' && tipo !== 'carrusel') return h
  var prompt = String((pieza && pieza.prompt_imagen) || '')
  var fuente = String((pieza && pieza.fuente_imagen) || '')
  var ref = fotoDeclarada(pieza)
  var foto = ref ? (ctx.fotos || []).filter(function (f) { return f.ref === ref })[0] : null
  var prot = { nombre: ctx.producto_del_brief, raices: ctx.raices_del_producto || [] }
  if (ref && !foto) falla('foto_referencia_inexistente', 'la pieza declara la foto «' + ref + '» de referencia y esa clave no existe entre las fotos que se le dieron')
  if (foto && foto.rol === 'otro_producto') falla('foto_referencia_de_otro_producto', 'la foto de referencia declarada (' + ref + ') muestra «' + (foto.producto || []).join(' + ') + '» y el producto del brief es «' + ctx.producto_del_brief + '»', true)
  else if (foto && (foto.rol === 'no_identificado' || foto.rol === 'varios_productos')) falla('foto_referencia_sin_producto_identificado', 'la foto de referencia declarada (' + ref + ') no tiene un producto identificado: el sistema no puede comprobar que sea «' + ctx.producto_del_brief + '»')
  if (ctx.sin_foto_del_producto && fuente === 'cliente' && prompt.trim()) falla('prompt_sin_foto_del_producto', 'no hay ninguna foto de «' + ctx.producto_del_brief + '», la fuente de la imagen es «cliente» y la pieza trae un prompt: se armó sobre la foto de otro producto', true)
  if (!ctx.sin_foto_del_producto && fuente === 'cliente' && prompt.trim() && !ref) falla('foto_referencia_no_declarada', 'la imagen es del cliente y la pieza no declara qué foto usó de referencia')
  if (ctx.sin_foto_del_producto) {
    var declaro = (pieza && Array.isArray(pieza.no_pude_cumplir) ? pieza.no_pude_cumplir : []).some(function (x) { return /foto/i.test(String(x)) })
    if (!declaro) falla('hueco_de_foto_no_declarado', 'no hay foto del producto del brief y la pieza no lo declara en «no_pude_cumplir»')
  }
  // el prompt nombra OTRO producto del cliente y no el del brief
  if (prompt.trim()) {
    var n = nombraProducto(prompt, ctx.catalogo, prot)
    if (n.otros.length && !n.propio) falla('prompt_nombra_otro_producto', 'el prompt de imagen nombra «' + n.otros.join(' + ') + '» y no el producto del brief («' + ctx.producto_del_brief + '»)', true)
  }
  return h
}

// ───────────────────────────── la pasada de VISIÓN · DISEÑADA Y APAGADA ─────────────────────────────
// 🔴 NO se construye con gasto (encargo Lenovo punto 3): requiere el GO de Emilio. Este módulo NO tiene red ni llamada a ningún modelo: sólo el CONTRATO y la regla de combinación,
// para que cuando haya GO la pasada sea enchufar un ejecutor y no rediseñar. Sin autorización explícita, `planDeVision` devuelve «apagada» y NO prepara ningún pedido.
//
// Diseño: una llamada pequeña por foto (UNA vez por huella: la misma imagen no se paga dos veces) que responde CONTRA EL CATÁLOGO del cliente (los productos de su plan), no contra una lista fija de platos:
//   entrada  → { foto: url del bucket, catalogo: [nombres de producto del cliente] }
//   salida   → { producto: <un nombre del catálogo> | 'ninguno' | 'no_se', seguridad: 0..1 }
// Combinación con el texto del post (`combinarFuentes`): el dueño GANA · texto y visión de acuerdo ⇒ 'caption' (con la visión de respaldo) · sólo uno habla ⇒ ése · chocan ⇒ 'conflicto' y NO se usa.
var VISION_ENCENDIDA = false
function planDeVision(filas, catalogo, autorizacion) {
  var pendientes = (filas || []).filter(function (f) { return f && !f.duplicado_de && !esLogo(f) && f.producto_fuente !== 'dueno' && f.producto_fuente !== 'vision' && !tieneProducto(f) })
  if (VISION_ENCENDIDA !== true || !autorizacion || autorizacion.go_emilio !== true) {
    return { estado: 'apagada', motivo: 'la pasada de visión requiere el GO de Emilio (gasto por foto) · no se prepara ningún pedido', pendientes: pendientes.length, pedidos: [] }
  }
  return { estado: 'autorizada_sin_ejecutor', pendientes: pendientes.length, pedidos: pendientes.map(function (f) { return { id: f.id, url: f.url, catalogo: (catalogo || []).map(function (e) { return e.nombre }) } }) }
}
/** { producto: [nombres], fuente } de lo que dicen el texto del post (`caption`), la visión (`vision`) y el dueño (`dueno`) · cada uno es { producto: [nombres] } o null */
function combinarFuentes(caption, vision, dueno) {
  var norm = function (v) { return v && Array.isArray(v.producto) ? v.producto.map(function (x) { return String(x).toLowerCase().trim() }).filter(Boolean).sort() : [] }
  var d = norm(dueno), c = norm(caption), v = norm(vision)
  if (d.length) return { producto: dueno.producto, fuente: 'dueno' }
  if (c.length && v.length) return c.join('|') === v.join('|') ? { producto: caption.producto, fuente: 'caption' } : { producto: [], fuente: 'conflicto' }
  if (c.length) return { producto: caption.producto, fuente: 'caption' }
  if (v.length) return { producto: vision.producto, fuente: 'vision' }
  return { producto: [], fuente: 'desconocido' }
}


// COPIA DE FOTOS · 3/5 · REVISAR · CC#1 · 2026-09-29 · 03-oct: SIN DUPLICADOS (huella SHA-256 · la portada de un carrusel es su hijo 1: se queda UNA y la repetida se DECLARA, no se sube) y el contexto de cada foto viaja a la tabla.
// (la lógica `sha256Hex` viene de fotos-contexto-logica.js, pegada arriba por el constructor) Mira lo que bajó CADA foto: si no es una imagen entera, se DECLARA aquí
// (fila estado=no_bajo con la causa exacta) y no pasa a subirse. Pasan solo las buenas, con su huella para verificar la subida.
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const metas = $('Fotos · lista').all().map((i) => i.json)
const entradas = $input.all()
const host = (u) => String(u).split('/')[2] || 'host desconocido'
const buenas = []
const fallas = []
const duplicadas = []
const vistas = {}
// el contexto que acompaña a cada fila (lo trae `Fotos · lista`)
const contexto = (m) => ({ caption: m.caption || null, posted_at: m.posted_at || null, post_url: m.post_url || null, posicion: m.posicion || null, medio: m.medio || null })
for (let i = 0; i < metas.length; i++) {
  const m = metas[i]
  const e = entradas[i]
  let causa = null
  let buf = null
  let ct = null
  if (!e) causa = 'sin respuesta del paso de descarga'
  else if (e.json && e.json.error) causa = 'red · ' + String(e.json.error.message || e.json.error).slice(0, 110)
  else if (e.json && e.json.statusCode && e.json.statusCode !== 200) causa = 'HTTP ' + e.json.statusCode
  else if (!e.binary || !e.binary.data) causa = 'la respuesta no trajo archivo'
  else {
    buf = await this.helpers.getBinaryDataBuffer(i, 'data')
    const h = buf.slice(0, 4).toString('hex')
    ct = h.startsWith('ffd8ff') ? 'image/jpeg' : h === '89504e47' ? 'image/png' : h === '52494646' && buf.slice(8, 12).toString('ascii') === 'WEBP' ? 'image/webp' : null
    if (!ct) causa = 'no es una imagen (empieza con ' + h + ' · ' + String(e.binary.data.mimeType || 'sin tipo') + ')'
    else if (buf.length > 10 * 1024 * 1024) causa = 'demasiado grande · ' + buf.length + ' B'
  }
  if (causa) {
    fallas.push({ client_id: m.client_id, owner_role: m.owner_role, handle: m.handle, post_id: m.post_id, tipo: m.tipo, url: null, estado: 'no_bajo', causa: causa + ' · ' + host(m.src), ...contexto(m) })
    continue
  }
  // 🔴 la MISMA imagen dos veces dentro de un post (portada = hijo 1) no se sube dos veces: se queda la primera y la repetida se declara
  const hash = sha256Hex(buf)
  const claveDup = String(m.post_id).replace(/-c\d+$/, '') + '|' + hash
  if (vistas[claveDup] !== undefined) { duplicadas.push({ post_id: m.post_id, igual_a: vistas[claveDup], hash }); continue }
  vistas[claveDup] = m.post_id
  const ext = ct === 'image/png' ? 'png' : ct === 'image/webp' ? 'webp' : 'jpg'
  buenas.push({
    json: { ...m, ct, hash_archivo: hash, bytes: buf.length, magic: buf.slice(0, 4).toString('hex'), path: m.client_id + '/' + m.owner_role + '/' + m.handle + '/' + m.post_id + '.' + ext },
    binary: { data: e.binary.data },
  })
}
// las que no bajaron se DECLARAN ya en la tabla (aunque nada más suba)
if (fallas.length) {
  const w = await this.helpers.httpRequest({
    url: SB + '/rest/v1/client_social_images?on_conflict=client_id,owner_role,handle,post_id', method: 'POST', json: true,
    returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, body: fallas,
    headers: { ...auth, 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' },
  })
  if (w.statusCode >= 300) throw new Error('COPIA_FOTOS_SIN_ANOTAR · la tabla respondió HTTP ' + w.statusCode + ' · ' + JSON.stringify(w.body).slice(0, 200))
}
const resumen = (fs) => fs.length + ' de ' + metas.length + ' · ' + fs.slice(0, 5).map((f) => f.handle + '/' + f.post_id + ' → ' + f.causa).join(' | ')
if (!buenas.length) {
  if (fallas.length) throw new Error('FOTOS_NO_BAJARON · ' + resumen(fallas))
  return []
}
buenas.forEach((b) => { b.json._fallas = fallas; b.json._total = metas.length; b.json._duplicadas = duplicadas })
return buenas

// COPIA DE FOTOS · 5/5 · ANOTAR · CC#1 · 2026-09-29 · 03-oct: cada fila guarda TODO su contexto (texto · fecha · enlace del post · posición · medio real · huella). Re-raspar completa las filas viejas (upsert). VERIFICA cada subida contra lo que se bajó (largo y firma del archivo) antes
// de anotarla como `ok`: una subida dañada se DECLARA (no_bajo · «subida dañada») y nunca se da por buena.
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const metas = $('Fotos · revisar').all().map((i) => i.json)
const subidas = $input.all()
const fallasPrevias = (metas[0] && metas[0]._fallas) || []
const total = (metas[0] && metas[0]._total) || metas.length
const duplicadas = (metas[0] && metas[0]._duplicadas) || []
const filas = []
for (let i = 0; i < metas.length; i++) {
  const m = metas[i]
  const s = subidas[i] && subidas[i].json
  const fila = { client_id: m.client_id, owner_role: m.owner_role, handle: m.handle, post_id: m.post_id, tipo: m.tipo, url: null, estado: 'no_bajo', causa: null, caption: m.caption || null, posted_at: m.posted_at || null, post_url: m.post_url || null, posicion: m.posicion || null, medio: m.medio || null, hash_archivo: m.hash_archivo || null }
  const url = SB + '/storage/v1/object/public/client-social-images/' + m.path
  if (!s || (s.statusCode && s.statusCode >= 300) || s.error) {
    fila.causa = 'subida rechazada · ' + (s && (s.statusCode ? 'HTTP ' + s.statusCode : String((s.error && s.error.message) || s.error).slice(0, 100)))
  } else {
    const c = await this.helpers.httpRequest({ url: url + '?nc=' + Date.now(), method: 'GET', encoding: 'arraybuffer', returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 })
    const g = Buffer.from(c.body || [])
    if (c.statusCode !== 200 || g.length !== m.bytes || g.slice(0, 4).toString('hex') !== m.magic) {
      fila.causa = 'subida dañada · esperado ' + m.bytes + ' B (' + m.magic + ') · hay ' + g.length + ' B (' + g.slice(0, 4).toString('hex') + ') · HTTP ' + c.statusCode
    } else {
      fila.url = url
      fila.estado = 'ok'
    }
  }
  filas.push(fila)
}
const w = await this.helpers.httpRequest({
  url: SB + '/rest/v1/client_social_images?on_conflict=client_id,owner_role,handle,post_id', method: 'POST', json: true,
  returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, body: filas,
  headers: { ...auth, 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' },
})
if (w.statusCode >= 300) throw new Error('COPIA_FOTOS_SIN_ANOTAR · la tabla respondió HTTP ' + w.statusCode + ' · ' + JSON.stringify(w.body).slice(0, 200))
const malas = filas.filter((f) => f.estado !== 'ok').concat(fallasPrevias)
if (malas.length) {
  throw new Error('FOTOS_NO_BAJARON · ' + malas.length + ' de ' + total + ' · ' + malas.slice(0, 5).map((f) => f.handle + '/' + f.post_id + ' → ' + f.causa).join(' | '))
}
return [{ json: { copia_fotos: 'ok', fotos: filas.length, duplicadas_no_subidas: duplicadas.length, duplicadas, perfiles: [...new Set(filas.map((f) => f.owner_role + ':' + f.handle))] } }]
